import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"3.4.12 Create Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-12-create-workspace/spec.md","filePath":"feature/agency-workspace/3-4-12-create-workspace/spec.md"}'),i={name:"feature/agency-workspace/3-4-12-create-workspace/spec.md"};function s(n,e,c,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="_3-4-12-create-workspace" tabindex="-1">3.4.12 Create Workspace <a class="header-anchor" href="#_3-4-12-create-workspace" aria-label="Permalink to &quot;3.4.12 Create Workspace&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.4.12</td></tr><tr><td>Feature</td><td>Create Workspace</td></tr><tr><td>Domain</td><td>Agency &amp; Workspace (FR 3.4)</td></tr><tr><td>Role</td><td>Agency Owner only — creates a Workspace inside their own Agency</td></tr><tr><td>Version</td><td>2.3 — 2026-09-24 — fixed BA conflict: only the Agency Owner may create a Workspace</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when the Agency Owner submits the Create Workspace form with a Workspace name and the target Agency.</p><p><strong>Fixed 2026-09-24:</strong> an earlier version of this spec/code allowed any active Agency member to create a Workspace (the <code>NOT_AGENCY_OWNER</code> guard only checked membership, not role — a real gap against BA, which restricts this to the Agency Owner). Now corrected in <code>WorkspaceServiceImpl.createWorkspace</code> to require <code>AgencyMemberRole.OWNER</code>.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Any member of the Agency in which the Workspace is created.</li><li><strong>Purpose:</strong> Creates a Workspace inside an Agency; the creator becomes its MANAGER by default, and members may optionally be assigned — including transferring the MANAGER role — at creation time.</li><li><strong>Interface:</strong> Create Workspace form — name input, Agency field, the extended Workspace profile fields (industry, company size, website, phone, location, description, brand colour, logo icon, tagline, founded year, Facebook/LinkedIn/Instagram links), and an optional member-assignment block.</li><li><strong>Data Processing:</strong> The system validates the request, creates the Workspace row, inserts the creator&#39;s membership in the same transaction, then applies any assignment entries — demoting the creator to CREATOR when the MANAGER role was transferred.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Create Workspace Screen:</p><ul><li>A single form screen scoped to one Agency.</li><li>Name input (required) and the target Agency (required).</li><li>Optional extended fields: industry, company size, website, phone, location, description, brand colour, logo icon, tagline, founded year, and social links.</li><li>Optional member-assignment block letting the user pick Agency members and a role each (MANAGER / CREATOR / CLIENT).</li><li>A &quot;Create&quot; action; on success the user is taken into the new Workspace.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> name; agencyId (carried in the request payload, not in the path).</li><li><strong>Input optional:</strong> industry (WorkspaceIndustry enum), companySize (CompanySize enum), website, phone, location, description, brandColor, logoIcon, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, assignMembers (list of <code>{userId, role}</code> with role in MANAGER / CREATOR / CLIENT).</li><li><strong>System data:</strong> The caller&#39;s authenticated identity; the Agency membership of the caller; default Workspace settings; the created Workspace identifier.</li><li><strong>Output:</strong> The created Workspace — id, name, agencyId, settings, industry, companySize, website, phone, location, description, brandColor, logoIcon, logoUrl, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, createdAt.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-24:</strong> Creating a workspace inserts the creator as a workspace_members row with role MANAGER (or CREATOR when the MANAGER role is transferred via <code>assignMembers</code>), isActive=true. (Note: the code builds the Workspace row directly and does not show an explicit slug-generation step; any slug behavior described elsewhere is design intent, not confirmed against this method — see report.)</li><li>If <code>assignMembers</code> names exactly one other user as MANAGER, the creator is automatically demoted to CREATOR and the chosen user holds MANAGER — a Workspace has exactly one active MANAGER at any time.</li><li>The Workspace row and the creator&#39;s membership row are created in a single transaction; the <code>assignMembers</code> entries are applied immediately afterwards.</li><li><code>name</code> empty or <code>agencyId</code> missing → 400 <code>VALIDATION_ERROR</code>.</li><li>More than one MANAGER entry in <code>assignMembers</code> besides the creator → 409 <code>MANAGER_ALREADY_ASSIGNED</code>.</li><li><strong>BR-29:</strong> Multi-tenancy — the caller must be an active member of the target Agency (its parent scope). On top of that, the caller must specifically hold the OWNER role in that Agency — otherwise 403 <code>NOT_AGENCY_OWNER</code>. Both checks are the first guard clause in <code>createWorkspace</code>, checked before the Workspace row is built.</li><li>An <code>assignMembers</code> entry whose user is not a member of that Agency → 403 <code>NOT_AGENCY_MEMBER</code>.</li><li>An <code>assignMembers</code> entry whose user record does not exist → <code>USER_NOT_FOUND</code>.</li><li>An <code>assignMembers</code> entry whose user already has an active membership in the new Workspace is skipped without error (idempotent).</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li><code>name</code> empty → Display: MSG02.</li><li><code>agencyId</code> missing → 400 <code>VALIDATION_ERROR</code>.</li><li><code>industry</code> must be a valid WorkspaceIndustry value; <code>companySize</code> must be a valid CompanySize value.</li><li><code>foundedYear</code>, when supplied, must be a numeric year.</li><li>Every <code>assignMembers</code> role must be one of MANAGER / CREATOR / CLIENT (BR-31 — workspace roles in code are the MemberRole enum: MANAGER, CREATOR, CLIENT; there is no workspace-level OWNER, OWNER exists only at Agency level).</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>User opens the Create Workspace form inside an Agency and fills in the name, the Agency, and any optional fields.</li><li>System verifies the caller is an active member of that Agency (BR-29).</li><li>System creates the Workspace row with default settings and records the caller as its creator.</li><li>System inserts the creator&#39;s membership with role MANAGER — or with role CREATOR when the MANAGER role is being transferred (BR-24).</li><li>System applies the <code>assignMembers</code> entries, inserting a membership row for each valid entry.</li><li>System returns the created Workspace and the user is taken into it; the MANAGER is either the creator or the user designated in <code>assignMembers</code>. Toast MSG31.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>1.a1: <code>name</code> empty → Display: MSG02. 1.a2: The user corrects the field and resubmits.</li><li>1.b1: <code>agencyId</code> missing → 400 <code>VALIDATION_ERROR</code>. 1.b2: The user selects an Agency and resubmits.</li><li>2.a1: Caller is not an active member of the target Agency, or is a member but not its OWNER (BR-29) → 403 <code>NOT_AGENCY_OWNER</code>, toast MSG39. 2.a2: The user is returned to the Agency list; the Workspace is not created.</li><li>5.a1: An <code>assignMembers</code> entry references a user outside the Agency → 403 <code>NOT_AGENCY_MEMBER</code>, toast MSG39. 5.a2: The user removes or corrects that entry and resubmits.</li><li>5.b1: An <code>assignMembers</code> entry references a user that does not exist → <code>USER_NOT_FOUND</code>, toast MSG38. 5.b2: The user removes or corrects that entry and resubmits.</li><li>5.c1: Two entries request MANAGER besides the creator (BR-05) → 409 <code>MANAGER_ALREADY_ASSIGNED</code>, toast MSG39. 5.c2: The user reduces the assignment to a single MANAGER and resubmits.</li><li>No <code>assignMembers</code> supplied → the creator is the only MANAGER.</li><li>The creator lists themselves in <code>assignMembers</code> as MANAGER → not treated as &quot;another user&quot;; the creator keeps MANAGER.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>A Workspace row exists inside the Agency.</li><li>A membership row exists for the creator (MANAGER by default, CREATOR when the role was transferred) and for every valid <code>assignMembers</code> entry.</li><li>The new Workspace has exactly one active MANAGER.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Creating a Workspace from a saved Template (see FR 3.4.17 Save Workspace Template — the reverse direction; creating from a template is a UX extension and not required).</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/01-organization-structure.html">01-organization-structure.md</a>, <a href="./../../../BA/03-agency-workspace-management.html">03-agency-workspace-management.md</a></p>',28)])])}const p=t(i,[["render",s]]);export{m as __pageData,p as default};
